import pickle

from classes import Level
from classes.Level import GMD_Level
from model import Transformer
import torch

device = torch.device("cuda" if torch.cuda.is_available() else "cpu")
print(f"Using device: {device}")

model_name = "temp_model"
with (open(f"models/{model_name}/vocab.pkl", "rb") as vocab_file,
      open(f"models/{model_name}/h_params.pkl", "rb") as params_file):
    vocab = pickle.load(vocab_file);
    h_params = pickle.load(params_file);


vocab_size = len(vocab) + 1

transformer = Transformer(
    vocab_size, vocab_size,
    h_params["D_MODEL"], h_params["NUM_HEADS"], h_params["NUM_LAYERS"],
    h_params["D_FF"], h_params["MAX_SEQ_LENGTH"], h_params["DROPOUT"]
)

transformer.load_state_dict(torch.load(f"models/{model_name}/transformer.pth"))
transformer.eval()

def encode(text, vocab):
    tokens = [obj for obj in text.split(";") if obj.strip()]
    # print(tokens)
    return [vocab.get(token, 0) for token in tokens]  # 0 for unknown tokens


def generate(transformer, src_tokens, max_len=10000, max_seq_length=500, temperature=.6):
    transformer.eval()
    with torch.no_grad():
        tgt = torch.tensor([1]).unsqueeze(0)  # start token

        for i in range(max_len):
            # Slide both windows to stay within max_seq_length
            src = torch.tensor(src_tokens[-max_seq_length:]).unsqueeze(0)
            tgt_window = tgt[:, -max_seq_length:]

            output = transformer(src, tgt_window)

            logits = output[0, -1, :]
            probs = torch.softmax(logits / temperature, dim=-1)
            next_token = torch.multinomial(probs, 1).item()

            if next_token == 0:
                break

            # Append to the full tgt sequence (not just the window)
            tgt = torch.cat([tgt, torch.tensor([[next_token]])], dim=1)
            # Also grow src_tokens so the src window slides forward too
            src_tokens = src_tokens + [next_token]
            print(f"{i}/{max_len} tokens generated: {i / max_len * 100:.2f}% Complete!")

    return tgt[0].tolist()

def decode(tokens, vocab):
    reverse_vocab = {idx: token for token, idx in vocab.items()}
    return ";".join(reverse_vocab.get(t, "?") for t in tokens)

